/bin/zsh -lc "python3 -B - <<'PY'
from pathlib import Path
import difflib
for snapshot in ('.pre-repair', '.baseline'):
    for filename in ('vault.py', 'app.py', 'test_regressions.py', 'test_public.py'):
        before = Path(snapshot, filename)
        after = Path(filename)
        if before.exists() and after.exists():
            print(''.join(difflib.unified_diff(before.read_text().splitlines(True), after.read_text().splitlines(True), fromfile=str(before), tofile=str(after))))
        elif after.exists():
            print(f'{snapshot}: {filename} is added; {len(after.read_text().splitlines())} lines')
PY"

